final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Amazon Verified Permissions policy store for the bookstore application. Declares a strict
  Cedar schema for the Bookstore namespace (Role, User, and Book entity types; View and
  ViewWithPremiumOffers actions; required request-context region attribute), attaches static
  Cedar policies for admin, publisher, named-user, customer premium-offer, and region
  restrictions, and publishes the policy store identifier through an SSM parameter.

Resources:

  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      Description: Bookstore application Amazon Verified Permissions policy store providing Cedar-based access control with strict schema validation
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {},
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long"
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User"
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String"
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  AdminViewBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: 'permit(principal in Bookstore::Role::"Admin", action == Bookstore::Action::"View", resource);'

  BlockedAdminViewBookForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: 'forbid(principal == Bookstore::User::"Bob", action == Bookstore::Action::"View", resource);'

  PublisherViewOwnBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: 'permit(principal in Bookstore::Role::"Publisher", action == Bookstore::Action::"View", resource) when { resource.owner == principal };'

  NamedUserViewNamedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: 'permit(principal == Bookstore::User::"Alice", action == Bookstore::Action::"View", resource == Bookstore::Book::"PrideAndPrejudice");'

  CustomerPremiumOffersPermitPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: 'permit(principal in Bookstore::Role::"Customer", action == Bookstore::Action::"ViewWithPremiumOffers", resource) when { principal.yearsAsMember >= 2 };'

  CustomerPremiumOffersForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: 'forbid(principal in Bookstore::Role::"Customer", action == Bookstore::Action::"ViewWithPremiumOffers", resource) when { principal.yearsAsMember < 2 };'

  NonUnitedStatesRegionForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: 'forbid(principal, action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"], resource) when { context.region != "United States" };'

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/verified-permissions/policy-store-id
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: Identifier of the bookstore Amazon Verified Permissions policy store, published for downstream consumption

Outputs:

  BookstorePolicyStoreId:
    Description: Identifier of the bookstore Amazon Verified Permissions policy store
    Value: !Ref BookstorePolicyStore

  BookstorePolicyStoreArn:
    Description: ARN of the bookstore Amazon Verified Permissions policy store
    Value: !GetAtt BookstorePolicyStore.Arn

  BookstorePolicyStoreIdParameterName:
    Description: Name of the SSM parameter that publishes the bookstore policy store identifier
    Value: !Ref PolicyStoreIdParameter

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Self-contained AWS AppSync GraphQL API "TodoAPIwithJs" with API key authentication,
  a DynamoDB table (with an owner-index GSI), JavaScript pipeline resolvers and
  JavaScript functions for full CRUD, an index-backed by-owner query, and real-time
  subscriptions for create/update/delete events.

Resources:

  # ---------------------------------------------------------------------------
  # DynamoDB table + owner-index GSI
  # ---------------------------------------------------------------------------
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true

  # ---------------------------------------------------------------------------
  # IAM role that AppSync assumes to talk to DynamoDB (least privilege)
  # ---------------------------------------------------------------------------
  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoDynamoDBAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/owner-index'

  # ---------------------------------------------------------------------------
  # AppSync GraphQL API + API key
  # ---------------------------------------------------------------------------
  TodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Description: API key for TodoAPIwithJs
      Expires: 1798761600

  # ---------------------------------------------------------------------------
  # GraphQL schema (inline SDL)
  # ---------------------------------------------------------------------------
  TodoApiSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          name: String
          description: String
          owner: String
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        input CreateTodoInput {
          id: ID
          name: String!
          description: String
          owner: String
        }

        input UpdateTodoInput {
          id: ID!
          name: String
          description: String
          owner: String
        }

        input DeleteTodoInput {
          id: ID!
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          todosByOwner(owner: String!): [Todo]
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): String
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

  # ---------------------------------------------------------------------------
  # Data sources
  # ---------------------------------------------------------------------------
  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  NoneDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: NoneDataSource
      Description: NONE data source used by subscription resolvers
      Type: NONE

  # ---------------------------------------------------------------------------
  # JavaScript functions (one per data operation)
  # ---------------------------------------------------------------------------
  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: getTodoFn
      Description: Get a single Todo item by id
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: listTodosFn
      Description: List all Todo items
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Scan',
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

  TodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: todosByOwnerFn
      Description: Query Todo items through the owner-index GSI
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Query',
            query: util.dynamodb.toMapValues({ owner: ctx.args.owner }),
            index: 'owner-index',
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: createTodoFn
      Description: Create a Todo item, stamping id/createdAt/updatedAt/owner
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input || {};
          const id = input.id || util.autoId();
          const now = util.time.nowISO8601();

          const item = {};
          const keys = Object.keys(input);
          for (let i = 0; i < keys.length; i++) {
            const key = keys[i];
            const value = input[key];
            if (value === undefined || value === null) {
              continue;
            }
            item[key] = value;
          }
          item.id = id;
          item.createdAt = now;
          item.updatedAt = now;

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: updateTodoFn
      Description: Update only the supplied Todo fields and refresh updatedAt
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input || {};
          const id = input.id;
          const now = util.time.nowISO8601();

          const expressionNames = { '#updatedAt': 'updatedAt' };
          const expressionValues = { ':updatedAt': util.dynamodb.toDynamoDB(now) };
          const setExpressions = ['#updatedAt = :updatedAt'];

          const keys = Object.keys(input);
          let index = 0;
          for (let i = 0; i < keys.length; i++) {
            const key = keys[i];
            if (key === 'id' || key === 'createdAt' || key === 'updatedAt') {
              continue;
            }
            const value = input[key];
            if (value === undefined || value === null) {
              continue;
            }
            const nameKey = '#field' + index;
            const valueKey = ':value' + index;
            expressionNames[nameKey] = key;
            expressionValues[valueKey] = util.dynamodb.toDynamoDB(value);
            setExpressions.push(nameKey + ' = ' + valueKey);
            index++;
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: id }),
            update: {
              expression: 'SET ' + setExpressions.join(', '),
              expressionNames: expressionNames,
              expressionValues: expressionValues,
            },
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: deleteTodoFn
      Description: Delete a Todo item by id
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input || {};
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
          };
        }

        export function response(ctx) {
          const input = ctx.args.input || {};
          return input.id;
        }

  # ---------------------------------------------------------------------------
  # Pipeline resolvers for Query fields
  # ---------------------------------------------------------------------------
  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt ListTodosFunction.FunctionId

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt TodosByOwnerFunction.FunctionId

  # ---------------------------------------------------------------------------
  # Pipeline resolvers for Mutation fields
  # ---------------------------------------------------------------------------
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt UpdateTodoFunction.FunctionId

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt DeleteTodoFunction.FunctionId

  # ---------------------------------------------------------------------------
  # Subscription resolvers (NONE data source, built-in fan-out)
  # ---------------------------------------------------------------------------
  OnCreateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Subscription
      FieldName: onCreateTodo
      Kind: UNIT
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return null;
        }

  OnUpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Subscription
      FieldName: onUpdateTodo
      Kind: UNIT
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return null;
        }

  OnDeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Subscription
      FieldName: onDeleteTodo
      Kind: UNIT
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return null;
        }

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
Outputs:
  GraphQLApiUrl:
    Description: AppSync GraphQL endpoint URL
    Value: !GetAtt TodoApi.GraphQLUrl

  GraphQLApiId:
    Description: AppSync GraphQL API ID
    Value: !GetAtt TodoApi.ApiId

  ApiKey:
    Description: AppSync API key value
    Value: !GetAtt TodoApiKey.ApiKey

  ApiKeyId:
    Description: AppSync API key ID
    Value: !GetAtt TodoApiKey.ApiKeyId

  TodoTableName:
    Description: DynamoDB Todo table name
    Value: !Ref TodoTable

AWSTemplateFormatVersion: '2010-09-09'
Description: SimpleTodoAPI - AWS AppSync GraphQL API with APPSYNC_JS JavaScript resolvers backed by a single DynamoDB table and an owner GSI.

Resources:

  # ---------------------------------------------------------------------------
  # DynamoDB table (primary key: id, GSI: owner-index on owner)
  # ---------------------------------------------------------------------------
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      Tags:
        - Key: Name
          Value: SimpleTodoAPI-Todos

  # ---------------------------------------------------------------------------
  # IAM service role assumed by AppSync to read/write the table and its index
  # ---------------------------------------------------------------------------
  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: !Sub '${AWS::StackName}-appsync-dynamodb-role'
      Description: Service role assumed by AppSync SimpleTodoAPI to access the Todo DynamoDB table
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  # ---------------------------------------------------------------------------
  # AppSync GraphQL API (API key auth)
  # ---------------------------------------------------------------------------
  SimpleTodoAPI:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
      XrayEnabled: true

  # API key is generated by AppSync; only the resource/id is managed here.
  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Description: API key for SimpleTodoAPI testing

  # ---------------------------------------------------------------------------
  # GraphQL schema
  # ---------------------------------------------------------------------------
  TodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Definition: |
        type Todo {
          id: ID!
          owner: String!
          title: String!
          description: String
          completed: Boolean!
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        input CreateTodoInput {
          id: ID
          owner: String!
          title: String!
          description: String
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          completed: Boolean
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          todosByOwner(owner: String!): [Todo]
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        schema {
          query: Query
          mutation: Mutation
        }

  # ---------------------------------------------------------------------------
  # Single DynamoDB data source shared by all six resolvers
  # ---------------------------------------------------------------------------
  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref 'AWS::Region'

  # ---------------------------------------------------------------------------
  # JavaScript (APPSYNC_JS) resolvers - Mutations
  # ---------------------------------------------------------------------------
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = input.id || util.autoId();
          const now = util.time.nowISO8601();

          const item = {
            id: id,
            owner: input.owner,
            title: input.title,
            completed: input.completed === true,
            createdAt: now,
            updatedAt: now
          };

          if (input.description !== undefined && input.description !== null) {
            item.description = input.description;
          }

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(item)
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const now = util.time.nowISO8601();

          const sets = [];
          const names = {};
          const values = {};

          if (input.title !== undefined && input.title !== null) {
            sets.push('#title = :title');
            names['#title'] = 'title';
            values[':title'] = input.title;
          }
          if (input.description !== undefined && input.description !== null) {
            sets.push('#description = :description');
            names['#description'] = 'description';
            values[':description'] = input.description;
          }
          if (input.completed !== undefined && input.completed !== null) {
            sets.push('#completed = :completed');
            names['#completed'] = 'completed';
            values[':completed'] = input.completed;
          }

          sets.push('#updatedAt = :updatedAt');
          names['#updatedAt'] = 'updatedAt';
          values[':updatedAt'] = now;

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: names,
              expressionValues: util.dynamodb.toMapValues(values)
            }
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

